        assert!(query.starts_with("INSERT INTO transactions"));
        assert!(query.contains("($1, $2, $3, $4, $5, $6::chain_enum, $7)"));
        assert!(query.ends_with("ON CONFLICT (chain, tx_hash) DO NOTHING"));
    }

