 31→        total_funding: BigDecimal,
 32→        fill_count: i64,
 33→        trade_sizes: Vec<BigDecimal>,
 34→        win_count: i64,
 35→        loss_count: i64,
 36→    }
 37→
 38→    let mut map: HashMap<String, CoinAgg> = HashMap::new();
 39→
 40→    for fill in fills {
 41→        let agg = map.entry(fill.coin.clone()).or_insert_with(|| CoinAgg {
 42→            total_closed_pnl: BigDecimal::from(0),
 43→            total_fees: BigDecimal::from(0),
 44→            total_funding: BigDecimal::from(0),
 45→            fill_count: 0,
 46→            trade_sizes: Vec::new(),
 47→            win_count: 0,
 48→            loss_count: 0,
 49→        });
 50→        agg.fill_count += 1;
 51→        if let Some(ref cpnl) = fill.closed_pnl {
 52→            agg.total_closed_pnl += cpnl;
 53→            if cpnl > &BigDecimal::from(0) {
 54→                agg.win_count += 1;
 55→            } else if cpnl < &BigDecimal::from(0) {
 56→                agg.loss_count += 1;
 57→            }
 58→        }
 59→        if let Some(ref fee) = fill.fee {
 60→            agg.total_fees += fee;
 61→        }
 62→        agg.trade_sizes.push(fill.size.clone());
 63→    }
 64→
 65→    for fp in funding {
 66→        let agg = map.entry(fp.coin.clone()).or_insert_with(|| CoinAgg {
 67→            total_closed_pnl: BigDecimal::from(0),
 68→            total_fees: BigDecimal::from(0),
 69→            total_funding: BigDecimal::from(0),
 70→            fill_count: 0,
 71→            trade_sizes: Vec::new(),
 72→            win_count: 0,
 73→            loss_count: 0,
 74→        });
 75→        agg.total_funding += &fp.amount;
 76→    }
 77→
 78→    let now = chrono::Utc::now();
 79→    let mut results: Vec<HlPnlSummary> = map
 80→        .into_iter()
 81→        .map(|(coin, agg)| {
 82→            let trade_count = agg.win_count + agg.loss_count;
 83→            let avg_trade_size = if agg.trade_sizes.is_empty() {
 84→                BigDecimal::from(0)
 85→            } else {
 86→                let total_size: BigDecimal = agg
 87→                    .trade_sizes
 88→                    .iter()
 89→                    .fold(BigDecimal::from(0), |acc, s| acc + s);
 90→                total_size / BigDecimal::from(agg.trade_sizes.len() as i64)
 91→            };
 92→            let net_pnl = &agg.total_closed_pnl + &agg.total_funding - &agg.total_fees;
 93→            HlPnlSummary {
 94→                id: Uuid::new_v4(),
 95→                wallet_address: wallet.to_string(),
 96→                coin,
 97→                network: network.to_string(),
 98→                period_start,
 99→                period_end,
100→                total_closed_pnl: agg.total_closed_pnl,
101→                total_funding: agg.total_funding,
102→                total_fees: agg.total_fees,
103→                net_pnl,
104→                trade_count,
105→                fill_count: agg.fill_count,
106→                avg_trade_size,
107→                win_count: agg.win_count,
108→                loss_count: agg.loss_count,
109→                dataset_version_id: None,
110→                created_at: now,
111→            }
112→        })
113→        .collect();
114→    results.sort_by(|a, b| a.coin.cmp(&b.coin));
115→    results
116→}
