118→/// Build trade history from fills by grouping into logical open/close sequences.
119→///
120→/// A trade begins when a fill has a direction containing "Open" and ends
121→/// when a fill has a direction containing "Close". If fills cannot be
122→/// grouped into explicit open/close pairs (e.g. all fills lack direction),
123→/// each fill with a non-zero closed_pnl is treated as a standalone trade.
124→pub fn build_trade_history(
125→    wallet: &str,
126→    network: &str,
127→    fills: &[HlFillRecord],
128→) -> Vec<HlTradeHistory> {
129→    let now = chrono::Utc::now();
130→
131→    // Group fills by coin
132→    let mut by_coin: HashMap<String, Vec<&HlFillRecord>> = HashMap::new();
133→    for fill in fills {
134→        by_coin.entry(fill.coin.clone()).or_default().push(fill);
135→    }
136→
137→    let mut trades = Vec::new();
138→
139→    for (coin, mut coin_fills) in by_coin {
140→        // Sort fills by fill_time ascending
141→        coin_fills.sort_by_key(|f| f.fill_time);
142→
143→        let has_direction_info = coin_fills.iter().any(|f| {
144→            f.direction
145→                .as_deref()
146→                .is_some_and(|d| d.contains("Open") || d.contains("Close"))
147→        });
148→
149→        if has_direction_info {
150→            // Group into open/close sequences
151→            let mut open_fills: Vec<&HlFillRecord> = Vec::new();
152→
153→            for fill in &coin_fills {
154→                let dir = fill.direction.as_deref().unwrap_or("");
155→                if dir.contains("Open") {
156→                    open_fills.push(fill);
157→                } else if dir.contains("Close") && !open_fills.is_empty() {
158→                    // Build trade from accumulated opens + this close
159→                    let entry_price = weighted_avg_price(&open_fills);
160→                    let total_size: BigDecimal = open_fills
161→                        .iter()
162→                        .fold(BigDecimal::from(0), |acc, f| acc + &f.size);
163→                    let total_fees: BigDecimal = open_fills
164→                        .iter()
165→                        .chain(std::iter::once(fill))
166→                        .fold(BigDecimal::from(0), |acc, f| {
167→                            acc + f.fee.as_ref().unwrap_or(&BigDecimal::from(0))
168→                        });
169→                    let side = open_fills
170→                        .first()
171→                        .map(|f| f.side.clone())
172→                        .unwrap_or_default();
173→                    let opened_at = open_fills.first().map(|f| f.fill_time).unwrap_or(0);
174→                    let num_fills = (open_fills.len() + 1) as i64;
175→
176→                    trades.push(HlTradeHistory {
177→                        id: Uuid::new_v4(),
178→                        wallet_address: wallet.to_string(),
179→                        coin: coin.clone(),
180→                        network: network.to_string(),
181→                        side,
182→                        entry_price,
183→                        exit_price: fill.price.clone(),
184→                        size: total_size,
185→                        opened_at,
186→                        closed_at: fill.fill_time,
187→                        realized_pnl: fill
188→                            .closed_pnl
189→                            .clone()
190→                            .unwrap_or_else(|| BigDecimal::from(0)),
191→                        fees: total_fees,
192→                        num_fills,
193→                        dataset_version_id: None,
194→                        created_at: now,
195→                    });
196→                    open_fills.clear();
197→                } else if dir.contains("Close") {
198→                    // Close without a preceding open — standalone trade
199→                    trades.push(HlTradeHistory {
200→                        id: Uuid::new_v4(),
201→                        wallet_address: wallet.to_string(),
202→                        coin: coin.clone(),
203→                        network: network.to_string(),
204→                        side: fill.side.clone(),
205→                        entry_price: fill.price.clone(),
206→                        exit_price: fill.price.clone(),
207→                        size: fill.size.clone(),
208→                        opened_at: fill.fill_time,
209→                        closed_at: fill.fill_time,
210→                        realized_pnl: fill
211→                            .closed_pnl
212→                            .clone()
213→                            .unwrap_or_else(|| BigDecimal::from(0)),
214→                        fees: fill.fee.clone().unwrap_or_else(|| BigDecimal::from(0)),
215→                        num_fills: 1,
216→                        dataset_version_id: None,
217→                        created_at: now,
218→                    });
219→                }
220→            }
221→        } else {
222→            // Fallback: each fill with closed_pnl becomes a standalone trade
223→            for fill in &coin_fills {
224→                if fill.closed_pnl.is_some() {
225→                    trades.push(HlTradeHistory {
226→                        id: Uuid::new_v4(),
227→                        wallet_address: wallet.to_string(),
228→                        coin: coin.clone(),
229→                        network: network.to_string(),
230→                        side: fill.side.clone(),
231→                        entry_price: fill.price.clone(),
232→                        exit_price: fill.price.clone(),
233→                        size: fill.size.clone(),
234→                        opened_at: fill.fill_time,
235→                        closed_at: fill.fill_time,
236→                        realized_pnl: fill
237→                            .closed_pnl
238→                            .clone()
239→                            .unwrap_or_else(|| BigDecimal::from(0)),
240→                        fees: fill.fee.clone().unwrap_or_else(|| BigDecimal::from(0)),
241→                        num_fills: 1,
242→                        dataset_version_id: None,
243→                        created_at: now,
244→                    });
245→                }
246→            }
247→        }
248→    }
249→
250→    trades.sort_by(|a, b| a.closed_at.cmp(&b.closed_at));
251→    trades
252→}
