254→/// Build per-trader analytics from PnL summaries and trade histories.
255→pub fn build_trader_analytics(
256→    wallet: &str,
257→    pnl_summaries: &[HlPnlSummary],
258→    trade_histories: &[HlTradeHistory],
259→) -> TraderAnalytics {
260→    let total_net_pnl = pnl_summaries
261→        .iter()
262→        .fold(BigDecimal::from(0), |acc, s| acc + &s.net_pnl);
263→
264→    let total_volume = trade_histories
265→        .iter()
266→        .fold(BigDecimal::from(0), |acc, t| acc + &t.size * &t.entry_price);
267→
268→    let total_trades = trade_histories.len() as i64;
269→
270→    let total_wins: i64 = pnl_summaries.iter().map(|s| s.win_count).sum();
271→    let total_losses: i64 = pnl_summaries.iter().map(|s| s.loss_count).sum();
272→    let total_resolved = total_wins + total_losses;
273→    let win_rate = if total_resolved > 0 {
274→        total_wins as f64 / total_resolved as f64
275→    } else {
276→        0.0
277→    };
278→
279→    let mut coin_map: HashMap<String, (BigDecimal, BigDecimal, i64, i64, i64)> = HashMap::new();
280→    for s in pnl_summaries {
281→        let entry = coin_map
282→            .entry(s.coin.clone())
283→            .or_insert_with(|| (BigDecimal::from(0), BigDecimal::from(0), 0, 0, 0));
284→        entry.0 += &s.net_pnl;
285→        entry.3 += s.win_count;
286→        entry.4 += s.loss_count;
287→    }
288→    for t in trade_histories {
289→        let entry = coin_map
290→            .entry(t.coin.clone())
291→            .or_insert_with(|| (BigDecimal::from(0), BigDecimal::from(0), 0, 0, 0));
292→        entry.1 += &t.size * &t.entry_price;
293→        entry.2 += 1;
294→    }
295→
296→    let mut coin_breakdown: Vec<CoinPnlSummary> = coin_map
297→        .into_iter()
298→        .map(
299→            |(coin, (net_pnl, volume, trade_count, win_count, loss_count))| CoinPnlSummary {
300→                coin,
301→                net_pnl,
302→                volume,
303→                trade_count,
304→                win_count,
305→                loss_count,
306→            },
307→        )
308→        .collect();
309→    coin_breakdown.sort_by(|a, b| a.coin.cmp(&b.coin));
310→
311→    TraderAnalytics {
312→        wallet_address: wallet.to_string(),
313→        total_net_pnl,
314→        total_volume,
315→        total_trades,
316→        win_rate,
317→        coin_breakdown,
318→    }
319→}
