321→/// Build per-coin market analytics from PnL summaries and trade histories.
322→pub fn build_market_analytics(
323→    pnl_summaries: &[HlPnlSummary],
324→    trade_histories: &[HlTradeHistory],
325→) -> MarketAnalytics {
326→    struct CoinAgg {
327→        volume: BigDecimal,
328→        traders: HashSet<String>,
329→        trade_count: i64,
330→        total_pnl: BigDecimal,
331→        sizes: Vec<BigDecimal>,
332→    }
333→
334→    let mut coin_map: HashMap<String, CoinAgg> = HashMap::new();
335→
336→    for s in pnl_summaries {
337→        let entry = coin_map.entry(s.coin.clone()).or_insert_with(|| CoinAgg {
338→            volume: BigDecimal::from(0),
339→            traders: HashSet::new(),
340→            trade_count: 0,
341→            total_pnl: BigDecimal::from(0),
342→            sizes: Vec::new(),
343→        });
344→        entry.traders.insert(s.wallet_address.clone());
345→        entry.total_pnl += &s.net_pnl;
346→    }
347→
348→    for t in trade_histories {
349→        let entry = coin_map.entry(t.coin.clone()).or_insert_with(|| CoinAgg {
350→            volume: BigDecimal::from(0),
351→            traders: HashSet::new(),
352→            trade_count: 0,
353→            total_pnl: BigDecimal::from(0),
354→            sizes: Vec::new(),
355→        });
356→        entry.volume += &t.size * &t.entry_price;
357→        entry.traders.insert(t.wallet_address.clone());
358→        entry.trade_count += 1;
359→        entry.sizes.push(t.size.clone());
360→    }
361→
362→    let mut all_traders: HashSet<String> = HashSet::new();
363→    let mut total_volume = BigDecimal::from(0);
364→
365→    let mut coins: Vec<CoinMarketSummary> = coin_map
366→        .into_iter()
367→        .map(|(coin, agg)| {
368→            for t in &agg.traders {
369→                all_traders.insert(t.clone());
370→            }
371→            total_volume += &agg.volume;
372→            let avg_trade_size = if agg.sizes.is_empty() {
373→                BigDecimal::from(0)
374→            } else {
375→                let sum: BigDecimal = agg.sizes.iter().fold(BigDecimal::from(0), |acc, s| acc + s);
376→                sum / BigDecimal::from(agg.sizes.len() as i64)
377→            };
378→            CoinMarketSummary {
379→                coin,
380→                total_volume: agg.volume,
381→                unique_traders: agg.traders.len(),
382→                total_trades: agg.trade_count,
383→                total_pnl: agg.total_pnl,
384→                avg_trade_size,
385→            }
386→        })
387→        .collect();
388→    coins.sort_by(|a, b| a.coin.cmp(&b.coin));
389→
390→    MarketAnalytics {
391→        coins,
392→        total_volume,
393→        total_unique_traders: all_traders.len(),
394→    }
395→}
