397→/// Weighted average price of a set of fills (size-weighted).
398→fn weighted_avg_price(fills: &[&HlFillRecord]) -> BigDecimal {
399→    if fills.is_empty() {
400→        return BigDecimal::from(0);
401→    }
402→    let total_size: BigDecimal = fills
403→        .iter()
404→        .fold(BigDecimal::from(0), |acc, f| acc + &f.size);
405→    if total_size == BigDecimal::from(0) {
406→        return fills[0].price.clone();
407→    }
408→    let weighted_sum: BigDecimal = fills
409→        .iter()
410→        .fold(BigDecimal::from(0), |acc, f| acc + &f.price * &f.size);
411→    weighted_sum / total_size
412→}
