            (DatasetName::HlPnlSummary, "\"hl_pnl_summary\""),
            (DatasetName::HlTradeHistory, "\"hl_trade_history\""),
        ];
        assert_eq!(cases.len(), 11, "must cover all 11 datasets");
        for (variant, expected_json) in cases {
