    fn dataset_name_serde_roundtrip() {
        let cases = [
            (DatasetName::LedgerEntries, "\"ledger_entries\""),
            (DatasetName::TokenTransfers, "\"token_transfers\""),
            (
                DatasetName::NativeBalanceDeltas,
                "\"native_balance_deltas\"",
