    // -- WalletLedgerRecord tests (P5-W1) --

    #[test]
    fn wallet_ledger_record_serde_roundtrip() {
        let record = WalletLedgerRecord {
            id: uuid::Uuid::new_v4(),
            raw_transaction_id: Some(uuid::Uuid::new_v4()),
            wallet_address: "0xWallet".to_string(),
