            let records = state
                .repo
                .query_wallet_ledger_records(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "balance_history" => {
            let records = state
                .repo
                .query_balance_snapshots(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_pnl_summary" => {
            let records = state
                .repo
                .query_hl_pnl_summary(
