            export_jobs: RwLock::new(HashMap::new()),
        });
        let app = test_router_with_state(Arc::clone(&state));

        let req1 = axum::http::Request::builder()
            .method("POST")
            .uri("/v1/ingest")
            .header("content-type", "application/json")
            .header("authorization", "Bearer secret")
