#[derive(Deserialize)]
struct RegisterTargetRequest {
    kind: String,
    network: String,
    address: Option<String>,
    filter_spec: Option<serde_json::Value>,
    mode: Option<String>,
    label: Option<String>,
}

#[derive(Deserialize)]
struct TargetListParams {
