/// Datasets queryable via the /v1/datasets/{name}/records endpoint.
/// Includes the six Silver datasets plus two Gold datasets (P5-W1).
const QUERYABLE_DATASETS: &[&str] = &[
    "token_transfers",
    "native_balance_deltas",
    "decoded_events",
    "hl_fills",
    "hl_funding",
    "positions",
    "wallet_ledger",
    "balance_history",
    "hl_pnl_summary",
    "hl_trade_history",
    "protocol_events",
    "pool_snapshots",
];

fn validate_dataset_name(name: &str) -> Result<(), AppError> {
    if name.is_empty() || name.len() > 64 {
        return Err(AppError::bad_request("Invalid dataset name length"));
    }
    if !name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
        return Err(AppError::bad_request(
            "Dataset name contains invalid characters",
        ));
    }
    Ok(())
}

async fn list_all_datasets(
    State(state): State<Arc<AppState>>,
) -> Result<Json<Vec<DatasetInfo>>, AppError> {
    let mut datasets = Vec::new();
    for ds in DatasetName::all() {
        let sql_name = ds.as_sql_str();
        let latest = state
            .repo
            .get_latest_dataset_version(sql_name)
            .await
            .map_err(AppError::internal)?;
        datasets.push(DatasetInfo {
            name: sql_name.to_string(),
            latest_version: latest.as_ref().map(|v| v.version),
            latest_version_status: latest.as_ref().map(|v| v.status.to_string()),
        });
    }
    Ok(Json(datasets))
}

async fn list_dataset_versions_handler(
    State(state): State<Arc<AppState>>,
    Path(name): Path<String>,
) -> Result<Json<Vec<DatasetVersion>>, AppError> {
    validate_dataset_name(&name)?;
    let versions = state
        .repo
        .list_dataset_versions(&name)
        .await
        .map_err(AppError::internal)?;
    Ok(Json(versions))
}

async fn query_dataset_records(
    State(state): State<Arc<AppState>>,
    Path(name): Path<String>,
    Query(params): Query<DatasetQueryParams>,
) -> Result<Json<serde_json::Value>, AppError> {
    validate_dataset_name(&name)?;
    if !QUERYABLE_DATASETS.contains(&name.as_str()) {
        return Err(AppError::bad_request(format!(
            "Dataset '{}' is not queryable via this endpoint. Queryable datasets: {}",
            name,
            QUERYABLE_DATASETS.join(", ")
        )));
    }
    validate_date_range(params.time_start, params.time_end)?;
    let limit = clamp_limit(params.limit);
    let offset = clamp_offset(params.offset);
    let net = params.network.as_deref();

    let result = match name.as_str() {
        "token_transfers" => {
            let records = state
                .repo
                .query_token_transfers(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "native_balance_deltas" => {
            let records = state
                .repo
                .query_native_balance_deltas(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "decoded_events" => {
            let records = state
                .repo
                .query_decoded_events(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_fills" => {
            let records = state
                .repo
                .query_hl_fill_records(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_funding" => {
            let records = state
                .repo
                .query_hl_funding_payments(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "positions" => {
            let records = state
                .repo
                .query_hl_position_changes(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "wallet_ledger" => {
            let records = state
                .repo
                .query_wallet_ledger_records(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "balance_history" => {
            let records = state
                .repo
                .query_balance_snapshots(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_pnl_summary" => {
            let records = state
                .repo
                .query_hl_pnl_summary(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_trade_history" => {
            let records = state
                .repo
                .query_hl_trade_history(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "protocol_events" => {
            let records = state
                .repo
                .query_protocol_events(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "pool_snapshots" => {
            let records = state
                .repo
                .query_pool_snapshots(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
